var script$f = {
  name: 'CWebcamModal',

  props: {
    buttonClass: {
      type: String,
      default: 'd-flex align-items-center h-100',
    },
    labels: {
      type: Object,
      default: () => ({}),
    },
  },

  data () {
    return {
      video: null,
      stream: null,
      capturedImage: null,
      processingWebcam: true,
      showErrorMessage: false,
    }
  },

  computed: {
    hasCapturedImage () {
      return !!this.capturedImage
    },
  },

  methods: {
    openWebcamModal () {
      this.$refs.webcamModal.show();
    },

    async initializeWebcam () {
      await this.$nextTick();

      this.startWebcam();
    },

    startWebcam () {
      this.showErrorMessage = false;

      // Get access to the camera
      navigator.mediaDevices.getUserMedia({
        video: {
          facingMode: 'user',
        },
      })
        .then(stream => {
          this.stream = stream;
          this.$refs.video.srcObject = stream;
        })
        .catch(err => {
          console.error('Error accessing the camera:', err);

          this.showErrorMessage = true;
        }).finally(() => {
          this.processingWebcam = false;
        });
    },

    capturePhoto () {
      const video = this.$refs.video;
      const canvas = document.createElement('canvas');
      canvas.width = video.videoWidth;
      canvas.height = video.videoHeight;
      canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height);

      this.capturedImage = canvas.toDataURL('image/jpeg');
    },

    uploadCapturedImage () {
      if (!this.capturedImage) {
        return
      }

      fetch(this.capturedImage).then(res => res.blob()).then(blob => {
        const imageSuffix = new Date().toISOString().replace(/[:.]/g, '-');
        const file = new File([blob], `webcam-image-${imageSuffix}.jpg`, { type: 'image/jpeg' });

        this.$emit('upload', file);
      });

      this.$refs.webcamModal.hide();
    },

    stopWebcam () {
      if (!this.stream) {
        return
      }

      this.stream.getTracks().forEach(track => track.stop());
    },

    handleCaptureClick () {
      if (this.hasCapturedImage) {
        this.uploadCapturedImage();
      } else {
        this.capturePhoto();
      }
    },

    handleCloseClick () {
      if (this.hasCapturedImage) {
        this.discardCapturedImage();
      } else {
        this.$refs.webcamModal.hide();
      }
    },

    closeCamera () {
      this.stopWebcam();
      this.capturedImage = null;
      this.processingWebcam = true;
    },

    discardCapturedImage () {
      this.capturedImage = null;
      this.startWebcam();
    },
  },
};

